// Runtime rendering verification with temporary cameras only; no player/input changes.
using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class PRPlayCheck {
 static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_PropRefinement/");static double start;static int first,last,captured;static List<string> errors=new List<string>();static List<float> times=new List<float>();
 public static object Run(){if(!Application.isPlaying)throw new Exception("Play required");start=EditorApplication.timeSinceStartup;first=last=Time.frameCount;captured=0;errors.Clear();times.Clear();Application.logMessageReceived+=Log;EditorApplication.update+=Tick;return new{started=true,firstFrame=first,changesToPlayerOrInput=0};}
 static void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Warning)errors.Add(type+": "+message);}
 static void Tick(){try{if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();double elapsed=EditorApplication.timeSinceStartup-start;if(Time.frameCount!=last){last=Time.frameCount;if(elapsed>1)times.Add(Time.unscaledDeltaTime*1000);}if(elapsed>1.5&&captured==0){Prop("CableReel");captured++;}if(elapsed>3&&captured==1){Prop("Forklift");captured++;}if(elapsed>4.5&&captured==2){Prop("Press");captured++;}if(elapsed>7)End(true);}catch(Exception ex){errors.Add("Review tool: "+ex);End(false);}}
 static void Prop(string kind){var t=UnityEngine.Object.FindObjectsByType<Transform>().First(x=>x.parent&&x.parent.name.StartsWith("1F_")&&x.name.StartsWith("F1_")&&x.name.Contains("_"+kind+"_"));var r=t.GetComponentsInChildren<Renderer>().First(x=>x.name=="PR_"+kind+"_LOD0");float d=Mathf.Max(r.bounds.size.x,r.bounds.size.y,r.bounds.size.z);Shot(kind,r.bounds.center+t.TransformDirection(new Vector3(-.72f,.37f,1.05f))*Mathf.Clamp(d*1.18f,.85f,5.5f),r.bounds.center,53);}
 static void Shot(string name,Vector3 p,Vector3 target,float fov){var go=new GameObject("TemporarySurfacePlayCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.enabled=false;c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=fov;c.nearClipPlane=.035f;c.farClipPlane=Camera.main.farClipPlane;c.useOcclusionCulling=true;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;Texture2D t=null;try{c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;t=new Texture2D(1600,1000,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1000),0,0);t.Apply();File.WriteAllBytes(Out+"play_"+name+".jpg",t.EncodeToJPG(94));}finally{RenderTexture.active=old;c.targetTexture=null;if(t)UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 static void End(bool complete){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;times.Sort();var result=new{complete,firstFrame=first,lastFrame=last,framesAdvanced=last-first,views=captured,mainCameraFar=Camera.main?Camera.main.farClipPlane:0,errors,medianMs=times.Count>0?times[times.Count/2]:0,p95Ms=times.Count>0?times[(int)((times.Count-1)*.95)]:0,changesToPlayerOrInput=0};File.WriteAllText(Out+"play.json",JsonConvert.SerializeObject(result,Formatting.Indented));}
}
